import React from 'react';
import { Link } from 'react-router-dom';

const Sidebar = ({ role }) => {
    return (
        <div style={{ width: '240px', minHeight: '100vh', background: '#414447', borderRight: '1px solid #5a6268', padding: '20px 0' }}>
            <div style={{ fontSize: '22px', fontWeight: '700', color: '#fff', padding: '0 24px 20px', borderBottom: '1px solid #5a6268', marginBottom: '10px' }}>Employee Management </div>
            <nav>
                {role === 'ADMIN' && (
                    <>
                        <Link to="/" style={{ display: 'block', padding: '12px 24px', color: '#fff', textDecoration: 'none' }}>
                            <i className="fa fa-desktop me-2"></i> Dashboard
                        </Link>
                        <Link to="/add-employee/_add" style={{ display: 'block', padding: '12px 24px', color: '#fff', textDecoration: 'none' }}>
                            <i className="fa fa-user-plus me-2"></i> Add Employee
                        </Link>
                    </>
                )}
                {role === 'EMPLOYEE' && (
                    <Link to="/dashboard" style={{ display: 'block', padding: '12px 24px', color: '#fff', textDecoration: 'none' }}>
                        <i className="fa fa-user-circle me-2"></i> My Profile
                    </Link>
                )}
            </nav>
        </div>
    );
};

export default Sidebar;
